-- Provider services: encrypted scoped credentials, bounded usage, durable routing and voice.
begin;
create table private.provider_credentials(ref uuid primary key,mission_id uuid not null references public.missions(id),account_id uuid not null references public.founder_accounts(id),provider text not null check(provider in('paypal','twilio','resend','shopify','browserbase','openai')),sandbox_mode boolean not null,encrypted jsonb not null,created_at timestamptz not null default clock_timestamp());
create table private.approval_token_vault(approval_id uuid primary key references public.approvals(id),mission_id uuid not null references public.missions(id),encrypted jsonb not null,created_at timestamptz not null default clock_timestamp());
create table public.service_budget_limits(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),provider text not null check(provider in('openai','browserbase')),maximum_units bigint not null check(maximum_units>0),created_at timestamptz not null default clock_timestamp());
create table public.service_reservations(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),provider text not null,task_key text not null,maximum_units bigint not null check(maximum_units>0),created_at timestamptz not null default clock_timestamp(),unique(mission_id,task_key));
create table public.service_usage_events(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),reservation_id uuid not null references public.service_reservations(id),status text not null check(status in('completed','ambiguous')),provider_reference text,used_units bigint,created_at timestamptz not null default clock_timestamp(),unique(reservation_id));
create table public.provider_references(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),provider text not null,provider_reference text not null,kind text not null,correlation jsonb not null,sandbox_mode boolean not null,created_at timestamptz not null default clock_timestamp(),unique(provider,provider_reference,sandbox_mode));
create table public.provider_drafts(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),task_key text not null,artifact_version_id uuid not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,task_key),foreign key(mission_id,artifact_version_id)references public.artifact_versions(mission_id,id));
create table public.provider_assets(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),mime_type text not null check(mime_type in('image/png','image/jpeg')),content_base64 text not null,payload_hash text not null,provider_reference text not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,provider_reference));
create table public.voice_sessions(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),task_id uuid not null,counterparty_id uuid not null,mandate_id uuid,twilio_ref uuid not null references private.provider_credentials(ref),openai_ref uuid not null references private.provider_credentials(ref),language text not null check(language in('ar','en')),disclosure text not null,recording_consent boolean not null default false,bounds jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,task_id),foreign key(mission_id,mandate_id)references public.mandates(mission_id,id));
alter table public.voice_sessions add column outreach_mandate_id uuid;
alter table public.voice_sessions add foreign key(mission_id,outreach_mandate_id)references public.mandates(mission_id,id);
create table public.counterparty_optouts(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),counterparty_id uuid not null references public.counterparties(id),source text not null,created_at timestamptz not null default clock_timestamp(),unique(counterparty_id));
create table public.payment_refunds(id uuid primary key default gen_random_uuid(),mission_id uuid not null,payment_id uuid not null,authorization_id uuid not null,receipt_id uuid not null unique,provider_refund_id text not null,amount_minor bigint not null check(amount_minor>0),currency text not null,sandbox_mode boolean not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,id),unique(authorization_id),foreign key(mission_id,payment_id)references public.payments(mission_id,id),foreign key(mission_id,authorization_id)references public.effect_authorizations(mission_id,id),foreign key(mission_id,receipt_id)references public.provider_receipts(mission_id,id));
create table public.refund_confirmations(id uuid primary key default gen_random_uuid(),mission_id uuid not null,refund_id uuid not null unique,event_id uuid not null,created_at timestamptz not null default clock_timestamp(),foreign key(mission_id,refund_id)references public.payment_refunds(mission_id,id),foreign key(mission_id,event_id)references public.events(mission_id,id));
create table public.provider_research(id uuid primary key default gen_random_uuid(),mission_id uuid not null,task_key text not null,evidence_id uuid not null,url text not null,created_at timestamptz not null default clock_timestamp(),unique(mission_id,task_key),foreign key(mission_id,evidence_id)references public.evidence(mission_id,id));
create table public.voice_session_events(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),session_id uuid not null references public.voice_sessions(id),kind text not null check(kind in('stream_started','transcript','fact','followup','ended','recording','optout','blocked')),event_key text not null,payload jsonb not null,created_at timestamptz not null default clock_timestamp(),unique(session_id,event_key));
create unique index voice_stream_once on public.voice_session_events(session_id)where kind='stream_started';
create unique index voice_end_once on public.voice_session_events(session_id)where kind='ended';
alter table public.messages add column approval_id uuid;
alter table public.messages add foreign key(mission_id,approval_id)references public.approvals(mission_id,id);
create unique index outbound_receipt_once on public.messages(receipt_id)where direction='outbound';
create unique index inbound_provider_once on public.messages(mission_id,channel,provider_id)where direction='inbound'and provider_id is not null;
create unique index voice_authorization_once on public.effect_authorizations(mission_id,(intent->>'taskId'))where intent->>'channel'='voice'and intent->>'action'='send_message';
do $$declare t text;begin foreach t in array array['service_budget_limits','service_reservations','service_usage_events','provider_references','provider_drafts','provider_assets','voice_sessions','voice_session_events','counterparty_optouts','payment_refunds','refund_confirmations','provider_research']loop
  execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);
  execute format('create policy tenant_scope on public.%I using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id))',t);
  execute format('create trigger immutable_row before update or delete on public.%I for each row execute function private.immutable_row()',t);
  execute format('grant select on public.%I to founder_role,policy_role,lead_role,specialist_role,voice_role,ingress_role',t);
end loop;end$$;
grant insert on public.provider_drafts to specialist_role;
grant insert on public.provider_research to specialist_role;
grant insert on public.provider_assets to policy_role;

create function public.store_provider_credential(p_mission uuid,p_ref uuid,p_account uuid,p_provider text,p_sandbox boolean,p_encrypted jsonb)returns void language plpgsql security definer set search_path=''as $$begin
  perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);
  if not exists(select from public.missions m join public.founder_accounts a on a.founder_id=m.founder_id where m.id=p_mission and a.id=p_account and a.provider=p_provider and a.status='connected'and m.sandbox_mode=p_sandbox and not exists(select from public.account_revocations r where r.account_id=a.id))then raise exception 'invariant_violation: provider account scope mismatch';end if;
  if not(p_encrypted?&array['iv','ciphertext','tag'])then raise exception 'validation: encrypted credential required';end if;
  insert into private.provider_credentials values(p_ref,p_mission,p_account,p_provider,p_sandbox,p_encrypted,clock_timestamp());
end$$;
create function public.resolve_provider_credential(p_mission uuid,p_ref uuid,p_provider text,p_sandbox boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare v private.provider_credentials;begin
  perform private.require_role(array['policy_role','ingress_role','voice_role']);perform private.assert_mission(p_mission);
  select c.*into strict v from private.provider_credentials c join public.missions m on m.id=c.mission_id join public.founder_accounts a on a.id=c.account_id and a.founder_id=m.founder_id where c.mission_id=p_mission and c.ref=p_ref and c.provider=p_provider and c.sandbox_mode=p_sandbox and m.sandbox_mode=p_sandbox and a.status='connected'and not exists(select from public.account_revocations r where r.account_id=a.id);
  return jsonb_build_object('encrypted',v.encrypted,'accountId',v.account_id,'ref',v.ref);
end$$;
create function public.provider_connection(p_mission uuid,p_provider text,p_account uuid default null)returns jsonb language plpgsql security definer set search_path=''as $$declare v private.provider_credentials;begin
  perform private.require_role(array['policy_role','ingress_role','voice_role']);perform private.assert_mission(p_mission);
  select c.*into strict v from private.provider_credentials c join public.founder_accounts a on a.id=c.account_id join public.missions m on m.id=c.mission_id and m.founder_id=a.founder_id where c.mission_id=p_mission and c.provider=p_provider and(p_account is null or c.account_id=p_account)and c.sandbox_mode=m.sandbox_mode and a.status='connected'and not exists(select from public.account_revocations r where r.account_id=a.id)order by c.created_at desc limit 1;
  return jsonb_build_object('ref',v.ref,'accountId',v.account_id,'sandboxMode',v.sandbox_mode);
end$$;
create function public.store_approval_token(p_mission uuid,p_approval uuid,p_encrypted jsonb)returns void language plpgsql security definer set search_path=''as $$begin
  perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);perform 1 from public.approvals where mission_id=p_mission and id=p_approval;if not found then raise exception 'invariant_violation: approval scope mismatch';end if;
  insert into private.approval_token_vault values(p_approval,p_mission,p_encrypted,clock_timestamp());
end$$;
create function public.resolve_approval_token(p_mission uuid,p_binding jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare v jsonb;begin
  perform private.require_role(array['policy_role']);perform private.assert_mission(p_mission);
  select jsonb_build_object('approvalId',a.id,'encrypted',t.encrypted)into v from private.approval_token_vault t join public.approvals a on a.id=t.approval_id where t.mission_id=p_mission and a.binding=p_binding and a.expires_at>clock_timestamp()and not exists(select from public.approval_consumptions c where c.approval_id=a.id)and not exists(select from public.approval_invalidations i where i.approval_id=a.id)order by a.created_at desc limit 1;return v;
end$$;
create function public.configure_service_budget(p_mission uuid,p_provider text,p_units bigint)returns void language plpgsql security definer set search_path=''as $$begin perform private.require_role(array['founder_role']);perform private.lock_mission(p_mission);insert into public.service_budget_limits(mission_id,provider,maximum_units)values(p_mission,p_provider,p_units);end$$;
create function public.reserve_service_budget(p_mission uuid,p_key text,p_provider text,p_units bigint)returns boolean language plpgsql security definer set search_path=''as $$declare v_cap bigint;v_used bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
  if p_units<=0 or length(p_key)<16 then raise exception 'validation: invalid service reservation';end if;
  if exists(select from public.service_reservations where mission_id=p_mission and task_key=p_key)then return false;end if;
  select maximum_units into v_cap from public.service_budget_limits where mission_id=p_mission and provider=p_provider order by created_at desc,id desc limit 1;
  select coalesce(sum(coalesce(e.used_units,r.maximum_units)),0)into v_used from public.service_reservations r left join public.service_usage_events e on e.reservation_id=r.id where r.mission_id=p_mission and r.provider=p_provider;
  if v_cap is null or v_used+p_units>v_cap then return false;end if;
  insert into public.service_reservations(mission_id,provider,task_key,maximum_units)values(p_mission,p_provider,p_key,p_units);return true;
end$$;
create function public.complete_service_budget(p_mission uuid,p_key text,p_provider_reference text,p_used bigint)returns void language plpgsql security definer set search_path=''as $$declare v public.service_reservations;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict v from public.service_reservations where mission_id=p_mission and task_key=p_key;
  if p_used is not null and(p_used<0 or p_used>v.maximum_units)then raise exception 'invariant_violation: service usage exceeds reservation';end if;
  insert into public.service_usage_events(mission_id,reservation_id,status,provider_reference,used_units)values(p_mission,v.id,case when p_provider_reference is null then'ambiguous'else'completed'end,p_provider_reference,p_used)on conflict(reservation_id)do nothing;
end$$;
create function public.record_provider_reference(p_mission uuid,p_provider text,p_reference text,p_kind text,p_correlation jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;v_sandbox boolean;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(p_correlation);select sandbox_mode into strict v_sandbox from public.missions where id=p_mission;
  insert into public.provider_references(mission_id,provider,provider_reference,kind,correlation,sandbox_mode)values(p_mission,p_provider,p_reference,p_kind,p_correlation,v_sandbox)on conflict(provider,provider_reference,sandbox_mode)do nothing returning id into v_id;
  if v_id is null then select id into v_id from public.provider_references where mission_id=p_mission and provider=p_provider and provider_reference=p_reference and sandbox_mode=v_sandbox and correlation=p_correlation;if v_id is null then raise exception 'invariant_violation: provider reference collision';end if;end if;return v_id;
end$$;
create function public.ingest_provider_event(p_mission uuid,p_provider text,p_key text,p_type text,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare v_id uuid;v_duplicate boolean;begin
  perform private.require_role(array['ingress_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(p_payload);
  insert into public.events(mission_id,type,payload,provider,provider_event_id,signature_verified)values(p_mission,p_type,p_payload,p_provider,p_key,true)on conflict(provider,provider_event_id)do nothing returning id into v_id;
  v_duplicate:=v_id is null;
  if v_duplicate then select id into v_id from public.events where mission_id=p_mission and provider=p_provider and provider_event_id=p_key;if v_id is null then raise exception 'invariant_violation: provider event tenant mismatch';end if;
  else insert into public.outbox(mission_id,type,payload)values(p_mission,p_type,jsonb_build_object('eventId',v_id,'provider',p_provider));end if;
  return jsonb_build_object('eventId',v_id,'duplicate',v_duplicate,'parked',p_type='webhook.parked');
end$$;
create function public.record_outbound_message(p_mission uuid,p_party uuid,p_reference text,p_channel text,p_original text,p_translation text,p_mandate uuid)returns uuid language plpgsql security definer set search_path=''as $$declare v_receipt uuid;v_authorization_id uuid;v_authorization public.effect_authorizations;v_thread uuid;v_id uuid;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(jsonb_build_object('original',p_original,'translation',p_translation));
  select r.id,a.id into v_receipt,v_authorization_id from public.provider_receipts r join public.effect_authorizations a on a.id=r.authorization_id and a.mission_id=r.mission_id where r.mission_id=p_mission and r.provider_reference=p_reference and a.intent->>'counterpartyId'=p_party::text and a.intent->>'action'='send_message';
  if v_receipt is null then raise exception 'invariant_violation: outbound message has no matching receipt';end if;
  select *into strict v_authorization from public.effect_authorizations where id=v_authorization_id and mission_id=p_mission;
  select id into v_id from public.messages where receipt_id=v_receipt and direction='outbound';if v_id is not null then return v_id;end if;
  select id into v_thread from public.threads where mission_id=p_mission and counterparty_id=p_party order by created_at limit 1;if v_thread is null then insert into public.threads(mission_id,counterparty_id)values(p_mission,p_party)returning id into v_thread;end if;
  insert into public.messages(mission_id,thread_id,channel,direction,original,translation,provider_id,mandate_id,approval_id,receipt_id)values(p_mission,v_thread,p_channel,'outbound',p_original,p_translation,p_reference,v_authorization.mandate_id,v_authorization.approval_id,v_receipt)returning id into v_id;return v_id;
end$$;
create function public.ingest_inbound_message(p_mission uuid,p_event uuid,p_channel text,p_reference text,p_sender text,p_text text)returns uuid language plpgsql security definer set search_path=''as $$declare v_party uuid;v_thread uuid;v_id uuid;begin
  perform private.require_role(array['ingress_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(jsonb_build_object('body',p_text));
  if not exists(select from public.events where id=p_event and mission_id=p_mission and signature_verified)then raise exception 'invariant_violation: inbound message has no verified event';end if;
  select c.id into v_party from public.counterparties c join public.missions m on m.founder_id=c.founder_id where m.id=p_mission and(case when p_channel='email'then lower(c.channels->>'email')=lower(p_sender)else c.channels->>'phone'=p_sender end)limit 1;
  if v_party is null then return null;end if;
  select id into v_thread from public.threads where mission_id=p_mission and counterparty_id=v_party order by created_at limit 1;if v_thread is null then insert into public.threads(mission_id,counterparty_id)values(p_mission,v_party)returning id into v_thread;end if;
  insert into public.messages(mission_id,thread_id,channel,direction,original,provider_id)values(p_mission,v_thread,p_channel,'inbound',p_text,p_reference)on conflict(mission_id,channel,provider_id)where direction='inbound'and provider_id is not null do nothing returning id into v_id;
  if lower(trim(p_text))in('stop','unsubscribe','توقف','إيقاف')then insert into public.counterparty_optouts(mission_id,counterparty_id,source)values(p_mission,v_party,'message:'||p_reference)on conflict(counterparty_id)do nothing;end if;return v_id;
end$$;
create function public.create_voice_session(p_mission uuid,p_task uuid,p_party uuid,p_mandate uuid,p_twilio uuid,p_openai uuid,p_language text,p_disclosure text,p_outreach uuid default null)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;v_bounds jsonb;v_consent boolean;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
  if not exists(select from public.runs where mission_id=p_mission and id=p_task)then raise exception 'validation: voice originating run missing';end if;
  select coalesce((c.verification->>'voiceRecordingConsent')::boolean,false)into strict v_consent from public.counterparties c join public.missions m on m.founder_id=c.founder_id where m.id=p_mission and c.id=p_party and not c.opt_out;
  if p_mandate is not null then select scope->'bounds'into strict v_bounds from public.mandates where mission_id=p_mission and id=p_mandate and type='negotiation'and expires_at>clock_timestamp()and scope->'counterpartyIds'?p_party::text and not exists(select from public.mandate_revocations where mandate_id=p_mandate);end if;
  if not exists(select from private.provider_credentials where ref=p_twilio and mission_id=p_mission and provider='twilio')or not exists(select from private.provider_credentials where ref=p_openai and mission_id=p_mission and provider='openai')then raise exception 'invariant_violation: voice credential scope mismatch';end if;
  insert into public.voice_sessions(mission_id,task_id,counterparty_id,mandate_id,twilio_ref,openai_ref,language,disclosure,recording_consent,bounds,outreach_mandate_id)values(p_mission,p_task,p_party,p_mandate,p_twilio,p_openai,p_language,p_disclosure,v_consent,coalesce(v_bounds,'{}'),p_outreach)on conflict(mission_id,task_id)do nothing returning id into v_id;
  if v_id is null then select id into v_id from public.voice_sessions where mission_id=p_mission and task_id=p_task and counterparty_id=p_party;if v_id is null then raise exception 'invariant_violation: voice task recipient changed';end if;end if;return v_id;
end$$;
create function public.voice_output_allowed(p_mission uuid,p_session uuid)returns boolean language plpgsql security definer set search_path=''as $$declare v public.voice_sessions;v_authority public.effect_authorizations;begin
  perform private.require_role(array['voice_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);select *into strict v from public.voice_sessions where id=p_session and mission_id=p_mission;
  if exists(select from public.voice_session_events where session_id=p_session and kind in('ended','optout'))or exists(select from public.counterparty_optouts where counterparty_id=v.counterparty_id)or exists(select from public.counterparties where id=v.counterparty_id and opt_out)or exists(select from public.mandate_revocations where mandate_id in(v.mandate_id,v.outreach_mandate_id))or(v.mandate_id is not null and not exists(select from public.mandates m where m.id=v.mandate_id and m.expires_at>clock_timestamp()and not exists(select from public.stale_marks where node_id=m.decision_id)))or(v.outreach_mandate_id is not null and not exists(select from public.mandates m where m.id=v.outreach_mandate_id and m.expires_at>clock_timestamp()and not exists(select from public.stale_marks where node_id=m.decision_id)))then return false;end if;
  select *into v_authority from public.effect_authorizations a where a.mission_id=p_mission and a.intent->>'taskId'=v.task_id::text and a.intent->>'action'='send_message'and a.intent->>'channel'='voice'and a.intent->>'counterpartyId'=v.counterparty_id::text;
  if v_authority.id is null or exists(select from public.approval_invalidations where approval_id=v_authority.approval_id)then return false;end if;
  perform private.check_version(p_mission,(v_authority.intent->>'artifactVersionId')::uuid);
  perform 1 from public.founder_accounts a join private.provider_credentials c on c.account_id=a.id where c.ref in(v.twilio_ref,v.openai_ref)for share of a;
  if exists(select from public.account_revocations r join private.provider_credentials c on c.account_id=r.account_id where c.ref in(v.twilio_ref,v.openai_ref))then return false;end if;return true;
end$$;
create function public.append_voice_event(p_mission uuid,p_session uuid,p_kind text,p_key text,p_payload jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare v_id uuid;v_commitment uuid;v public.voice_sessions;begin
  perform private.require_role(array['voice_role','ingress_role']);perform private.lock_mission(p_mission);perform private.assert_safe_content(p_payload);select *into strict v from public.voice_sessions where id=p_session and mission_id=p_mission;
  if p_kind='transcript'and not v.recording_consent then raise exception 'invariant_violation: transcript retention consent absent';end if;
  if p_kind='stream_started'and not exists(select from public.provider_references where mission_id=p_mission and provider='twilio'and provider_reference=p_payload->>'callSid'and correlation->>'voiceSessionId'=p_session::text)then raise exception 'invariant_violation: voice call correlation mismatch';end if;
  insert into public.voice_session_events(mission_id,session_id,kind,event_key,payload)values(p_mission,p_session,p_kind,p_key,p_payload)on conflict(session_id,event_key)do nothing returning id into v_id;
  if p_kind='fact'and v_id is not null then perform public.append_evidence(p_mission,'supply','verbal_terms','claimed',p_payload,'document','voice:'||p_session::text);end if;
  if p_kind='optout'and v_id is not null then insert into public.counterparty_optouts(mission_id,counterparty_id,source)values(p_mission,v.counterparty_id,'voice:'||p_session::text)on conflict(counterparty_id)do nothing;end if;
  if p_kind='ended'and v_id is not null then
    insert into public.commitments(mission_id,party_id,direction,description,due_at,actor_id)values(p_mission,v.counterparty_id,'outbound','Send written confirmation of the call; verbal terms remain claimed until acknowledged.',clock_timestamp()+interval '15 minutes',private.actor_id())returning id into v_commitment;
    insert into public.commitment_states(mission_id,commitment_id,status)values(p_mission,v_commitment,'open');
    insert into public.outbox(mission_id,type,payload)values(p_mission,'call.ended',jsonb_build_object('sessionId',p_session,'confirmationDueAt',clock_timestamp()+interval '15 minutes'));
  end if;return v_id;
end$$;
create function public.bind_voice_call(p_mission uuid,p_session uuid,p_call_sid text)returns void language plpgsql security definer set search_path=''as $$declare v public.voice_sessions;v_sandbox boolean;begin
  perform private.require_role(array['voice_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);select *into strict v from public.voice_sessions where mission_id=p_mission and id=p_session;
  if p_call_sid!~'^CA[a-fA-F0-9]{32}$'or exists(select from public.provider_references where mission_id=p_mission and provider='twilio'and correlation->>'voiceSessionId'=p_session::text and provider_reference<>p_call_sid)then raise exception 'invariant_violation: voice call id changed';end if;
  if not exists(select from public.effect_authorizations a where a.mission_id=p_mission and a.intent->>'taskId'=v.task_id::text and a.intent->>'counterpartyId'=v.counterparty_id::text and a.intent->>'action'='send_message'and a.intent->>'channel'='voice'and(select s.status from public.effect_states s where s.authorization_id=a.id order by s.created_at desc,s.id desc limit 1)in('started','performed'))then raise exception 'invariant_violation: voice call has no dispatched authorization';end if;
  select sandbox_mode into strict v_sandbox from public.missions where id=p_mission;
  insert into public.provider_references(mission_id,provider,provider_reference,kind,correlation,sandbox_mode)values(p_mission,'twilio',p_call_sid,'voice_call',jsonb_build_object('voiceSessionId',p_session,'counterpartyId',v.counterparty_id),v_sandbox)on conflict(provider,provider_reference,sandbox_mode)do nothing;
  if not exists(select from public.provider_references where mission_id=p_mission and provider='twilio'and provider_reference=p_call_sid and correlation->>'voiceSessionId'=p_session::text)then raise exception 'invariant_violation: call belongs to another session';end if;
end$$;
create function public.counterparty_opted_out(p_mission uuid,p_party uuid)returns boolean language plpgsql security definer stable set search_path=''as $$begin perform private.assert_mission(p_mission);return exists(select from public.counterparty_optouts o join public.counterparties c on c.id=o.counterparty_id join public.missions m on m.founder_id=c.founder_id where m.id=p_mission and o.counterparty_id=p_party);end$$;
create function private.block_optedout_effect()returns trigger language plpgsql security definer set search_path=''as $$begin if exists(select from public.counterparty_optouts where counterparty_id=(new.intent->>'counterpartyId')::uuid)then raise exception 'invariant_violation: counterparty opted out';end if;return new;end$$;
create trigger block_optedout_effect before insert on public.effect_authorizations for each row execute function private.block_optedout_effect();
create function public.register_payment_refund(p_mission uuid,p_receipt uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.provider_receipts;a public.effect_authorizations;p public.payments;v_id uuid;v_sum bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict r from public.provider_receipts where mission_id=p_mission and id=p_receipt and provider='paypal'and operation='payment_refund';select *into strict a from public.effect_authorizations where mission_id=p_mission and id=r.authorization_id and approval_id is not null;
  select pmt.*into strict p from public.payments pmt join public.provider_receipts original on original.authorization_id=pmt.authorization_id where pmt.mission_id=p_mission and pmt.provider='paypal'and original.provider_reference=r.data->>'captureId'and original.data->>'orderId'=r.data->>'orderId'and pmt.payee_id=(a.intent->>'counterpartyId')::uuid and pmt.currency=a.intent->>'currency'and pmt.sandbox_mode=r.sandbox_mode;
  select id into v_id from public.payment_refunds where mission_id=p_mission and receipt_id=p_receipt;if v_id is not null then return v_id;end if;
  select coalesce(sum(amount_minor),0)into v_sum from public.payment_refunds where payment_id=p.id;if a.amount_minor<=0 or a.amount_minor+v_sum>p.amount_minor then raise exception 'invariant_violation: refund exceeds original payment';end if;
  insert into public.payment_refunds(mission_id,payment_id,authorization_id,receipt_id,provider_refund_id,amount_minor,currency,sandbox_mode)values(p_mission,p.id,a.id,r.id,r.provider_reference,a.amount_minor,p.currency,p.sandbox_mode)returning id into v_id;return v_id;
end$$;
create function public.confirm_payment_refund(p_mission uuid,p_refund uuid,p_event uuid)returns uuid language plpgsql security definer set search_path=''as $$declare f public.payment_refunds;p public.payments;r public.provider_receipts;v_id uuid;v_total bigint;begin
  perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select *into strict f from public.payment_refunds where mission_id=p_mission and id=p_refund;select *into strict p from public.payments where mission_id=p_mission and id=f.payment_id;select *into strict r from public.provider_receipts where mission_id=p_mission and id=f.receipt_id;
  if not exists(select from public.events e where e.id=p_event and e.mission_id=p_mission and e.provider='paypal'and e.signature_verified and e.type in('payment.refunded','payment.refund_verified_poll')and e.payload->>'refundId'=f.id::text and e.payload->>'providerReference'=f.provider_refund_id and e.payload->>'orderId'=r.data->>'orderId'and e.payload->>'captureId'=r.data->>'captureId'and e.payload->>'payeeId'=p.payee_id::text and(e.payload->>'amountMinor')::bigint=f.amount_minor and e.payload->>'currency'=f.currency and(e.payload->>'sandboxMode')::boolean=f.sandbox_mode)then raise exception 'invariant_violation: exact verified refund confirmation required';end if;
  if not exists(select from public.payment_states where payment_id=p.id and state='captured')then raise exception 'invariant_violation: original payment settlement must be reconciled first';end if;
  select id into v_id from public.refund_confirmations where refund_id=f.id;if v_id is not null then return v_id;end if;
  insert into public.refund_confirmations(mission_id,refund_id,event_id)values(p_mission,f.id,p_event)returning id into v_id;
  insert into public.money_ledger(mission_id,kind,amount_minor,currency,basis,envelope,ref_id,receipt_id,confirmation_event_id,sandbox_mode)values(p_mission,'refund',f.amount_minor,f.currency,'accepted',p.purpose,p.id,f.receipt_id,p_event,f.sandbox_mode);
  select coalesce(sum(x.amount_minor),0)into v_total from public.payment_refunds x join public.refund_confirmations c on c.refund_id=x.id where x.payment_id=p.id;if v_total=p.amount_minor then insert into public.payment_states(mission_id,payment_id,state,receipt_id,confirmation_event_id)values(p_mission,p.id,'refunded',f.receipt_id,p_event);end if;
  insert into public.outbox(mission_id,type,payload)values(p_mission,'payment.refunded',jsonb_build_object('paymentId',p.id,'refundId',f.id));return v_id;
end$$;
revoke execute on all functions in schema public from public;
grant execute on function public.store_provider_credential(uuid,uuid,uuid,text,boolean,jsonb),public.store_approval_token(uuid,uuid,jsonb),public.configure_service_budget(uuid,text,bigint)to founder_role;
grant execute on function public.resolve_provider_credential(uuid,uuid,text,boolean),public.provider_connection(uuid,text,uuid)to policy_role,ingress_role,voice_role;
grant execute on function public.resolve_approval_token(uuid,jsonb),public.reserve_service_budget(uuid,text,text,bigint),public.complete_service_budget(uuid,text,text,bigint),public.record_provider_reference(uuid,text,text,text,jsonb),public.create_voice_session(uuid,uuid,uuid,uuid,uuid,uuid,text,text,uuid),public.record_outbound_message(uuid,uuid,text,text,text,text,uuid)to policy_role;
grant execute on function public.ingest_provider_event(uuid,text,text,text,jsonb)to ingress_role;
grant execute on function public.ingest_inbound_message(uuid,uuid,text,text,text,text)to ingress_role;
grant execute on function public.voice_output_allowed(uuid,uuid),public.bind_voice_call(uuid,uuid,text)to voice_role;
grant execute on function public.counterparty_opted_out(uuid,uuid)to policy_role,voice_role,ingress_role;
grant execute on function public.append_voice_event(uuid,uuid,text,text,jsonb)to voice_role,ingress_role;
grant execute on function public.register_payment_refund(uuid,uuid),public.confirm_payment_refund(uuid,uuid,uuid)to policy_role;
commit;
